#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")/.."

# Build the debug app for the iOS simulator, install it on an iPhone simulator
# and print that simulator's UDID. For `scripts/native-e2e.sh --ios`; needs
# macOS and Xcode.
#
#   udid=$(bash scripts/ios-sim-build.sh <derived-data dir>)
#
# Uses a booted iPhone simulator, else boots the newest one available. The
# project is generated by a prebuild scoped to iOS (app/ios/ is a build product)
# with the committed Podfile.lock. A debug build loads its JavaScript from Metro
# at 127.0.0.1:8081, and on the simulator 127.0.0.1 is this machine, so the
# Firebase emulators need no mapping either.

[ "$(uname)" = Darwin ] || { echo "ios-sim-build.sh: needs macOS and Xcode" >&2; exit 2; }
DERIVED="${1:?usage: bash scripts/ios-sim-build.sh <derived-data dir>}"

udid=$(xcrun simctl list devices available -j | node -e '
  const { devices } = JSON.parse(require("node:fs").readFileSync(0, "utf8"));
  const phones = Object.entries(devices)
    .filter(([runtime]) => /SimRuntime\.iOS-/.test(runtime))
    .flatMap(([runtime, list]) => list.map((device) => ({ ...device, runtime })))
    .filter((device) => /^iPhone/.test(device.name));
  const newest = (a, b) => b.runtime.localeCompare(a.runtime, undefined, { numeric: true });
  const pick = phones.find((device) => device.state === "Booted") ?? phones.sort(newest)[0];
  if (!pick) { console.error("no iPhone simulator is available"); process.exit(1); }
  console.log(pick.udid);')
xcrun simctl boot "$udid" 2>/dev/null || true
xcrun simctl bootstatus "$udid" -b >&2

( cd app && npx --no-install expo prebuild --platform ios --no-install >&2 )
cp app/Podfile.lock app/ios/Podfile.lock
( cd app/ios && pod install >&2 )
workspace=$(find app/ios -maxdepth 1 -name '*.xcworkspace' | head -1)
scheme=$(basename "$workspace" .xcworkspace)
xcodebuild -workspace "$workspace" -scheme "$scheme" -configuration Debug -sdk iphonesimulator \
  -destination "id=$udid" -derivedDataPath "$DERIVED" CODE_SIGNING_ALLOWED=NO -quiet build >&2
app=$(find "$DERIVED/Build/Products/Debug-iphonesimulator" -maxdepth 1 -name '*.app' | head -1)
[ -n "$app" ] || { echo "ios-sim-build.sh: the build made no .app" >&2; exit 1; }
xcrun simctl install "$udid" "$app"
echo "$udid"
